//DEPS org.springframework:spring-context:6.1.14
import org.springframework.context.annotation.*;
import org.springframework.beans.factory.annotation.Value;
public class Lesson {
static class Note { String text; public void prepare() { text = "Ready"; } }
@Configuration
static class Config {
@Bean(initMethod="prepare") Note note() { return new Note(); }
}
public static void main(String[] args) {
 try (var context = new AnnotationConfigApplicationContext(Config.class)) {
System.out.println(context.getBean(Note.class).text);
 }
}
}
